[Form]
public class METOrderExtractScreen extends FormRun
{
    METOrderExtractScreenParameters     metOrderExtractScreenParameters;
    METorderExtractScreenProcessor      metOrderExtractScreenProcessor;
    InventLocationId                    csdWareHouse;
    METNumberOfCustomers                csdCustomerLimit;

    boolean                             selectAll;       
   
    [FormObservable]
    METTotalPallets                     totalPallets;
    FormObservableLink                  markedObservableLink;
    METOrderExtractScreenTmp            metOrderExtractScreenTmp;
    Args                                args;
    #Task

    //Bug 229712 CB628 - Update status in extraction screen got refresh issue -start
    #SysSystemDefinedButtons
    FormCommandButtonControl            editbutton;
	//Bug 229712 CB628 - Update status in extraction screen got refresh issue -end

    Map metricsCacheMap;
    Map lastPickListCacheMap;

}

/// <summary>
/// Calculates total pallets.
/// </summary>
/// <returns>pallets</returns>
public display METTotalPallets totalPallets()
{
    return totalPallets;
}

/// <summary>
/// MetricsCacheMap used by Load Planning report
/// </summary>
/// <returns>Map</returns>
public Map getMetricsCacheMap()
{
    return metricsCacheMap;
}

    /// <summary>
    /// Populates the <c>METOrderExtractScreenTmp</c> table.
    /// </summary>
    public void populateOrders()
    {
        METProcMetrics procMetrics = METProcMetricsScope::current();

        metricsCacheMap = new Map(Types::Int64, Types::Container);
        lastPickListCacheMap = new Map(Types::String, Types::Container);

        delete_from METOrderExtractScreenTmpDS;

        if (this.args().parmObject() == null)
        {
            metOrderExtractScreenParameters = METOrderExtractScreenParameters::construct();
        }
        else
        {
            metOrderExtractScreenParameters = this.args().parmObject() as METOrderExtractScreenParameters;
        }

        metOrderExtractScreenParameters.loadLastValue(formStr(METOrderExtractScreen));

        metOrderExtractScreenProcessor = METOrderExtractScreenProcessor::construct(METOrderExtractScreenTmpDS, metOrderExtractScreenParameters);

        //CS - CB173_SalesOrderExtract - PS
        if (metOrderExtractScreenProcessor)
        {
            metOrderExtractScreenProcessor.parmMETOrderExtractScreenParams(metOrderExtractScreenParameters);
            metOrderExtractScreenTmp = metOrderExtractScreenProcessor.parmMETOrderExtractScreenTmp();
            METOrderExtractScreenTmpDS.linkPhysicalTableInstance(metOrderExtractScreenTmp);
            container   con = metOrderExtractScreenProcessor.parmCon();
            metOrderExtractScreenProcessor.parmMETOrderExtractScreenTmp(metOrderExtractScreenTmp);
        
            //Bug 229712 CB628 - Update status in extraction screen got refresh issue -start
            if (conLen(con) > 0)
            {
                MetFormActionPaneTabControl.enabled(true);
                editbutton.enabled(true);
            }
            else
            {
                MetFormActionPaneTabControl.enabled(false);
                editbutton.enabled(false);
            }
            //Bug 229712 CB628 - Update status in extraction screen got refresh issue -end

            METOrderExtractScreenTmpDS_DS.research();
        }
        
        //CE - CB173_SalesOrderExtract - PS
        totalPallets = metOrderExtractScreenProcessor.parmTotalpallets();

        SalesTable_ds.executeQuery();

        if (procMetrics)
        {
            procMetrics.setDescription(2, strFmt('Extract parameters - Route: %1, Site: %2, Warehouse: %3 From: %4, To: %5, Extracted: %6, Split group: %7 Order type: %8 Cust account: %9',
            metOrderExtractScreenParameters.parmRoute(),
            metOrderExtractScreenParameters.parmSite(),
            metOrderExtractScreenParameters.parmWarehouse(),
            metOrderExtractScreenParameters.parmShippingDateConfirmFrom(),
            metOrderExtractScreenParameters.parmShippingDateConfirmTo(),
            metOrderExtractScreenParameters.parmExtracted(),
            metOrderExtractScreenParameters.parmOrderSplitGroup(),
            metOrderExtractScreenParameters.parmOrderType(),
            metOrderExtractScreenParameters.parmCustAccount()));

            select count(RecId) from metOrderExtractScreenTmp;

            procMetrics.setTotalCount(metOrderExtractScreenTmp.RecId);
            procMetrics.beginTrace('Populate orders - Sales order extract screen');

            SalesLine salesLineLoc;
            METSalesLine metSalesLineLoc;

            select count(RecId) from salesLineLoc
                join RecId from metSalesLineLoc
                    where metSalesLineLoc.SalesLine == salesLineLoc.RecId
                    && metSalesLineLoc.OrderExtractStatus != METOrderExtractStatus::Extracted
                join metOrderExtractScreenTmp
                    where salesLineLoc.SalesId == metOrderExtractScreenTmp.SalesId;

            procMetrics.incLineCount(salesLineLoc.RecId);
        }
    }

    /// <summary>
    /// Form refresh logic.
    /// </summary>
    private void refresh()
    {
        METProcMetrics  procMetrics = METProcMetrics::construct(METBatchLogOperation::SalesOrderExtractScreen);

        using (METProcMetricsScope procMetricsScope = METProcMetricsScope::constructWithErrorHandling(procMetrics))
        {
            element.populateOrders();

            procMetrics.endTrace();
        }
    }

    /// <summary>
    /// Form initialise
    /// </summary>
    public void init()
    {
        super();
        markedObservableLink = new FormObservableLink();
        OrderExtractGrid.footerShown(true);

        //Bug 229712 CB628 - Update status in extraction screen got refresh issue -start
        editbutton  = this.control(this.controlId(#SystemDefinedViewEditButton)) as FormCommandButtonControl;
        editbutton.enabled(false);
        //Bug 229712 CB628 - Update status in extraction screen got refresh issue -end
    }

    public container lastPickListCache(SalesId _salesId)
    {
        if (lastPickListCacheMap.exists(_salesId))
        {
            return lastPickListCacheMap.lookup(_salesId);
        }

        WMSPickingRoute     wmsPickingRoute;
            
        select firstonly pickingRouteID, CreatedDateTime, CreatedBy from wmsPickingRoute
            order by CreatedDateTime desc
                where wmsPickingRoute.transRefId == _salesId
                   && wmsPickingRoute.transType == InventTransType::Sales;

        container result = [wmsPickingRoute.pickingRouteID, wmsPickingRoute.CreatedDateTime, wmsPickingRoute.CreatedBy];

        lastPickListCacheMap.insert(_salesId, result);

        return result;
    }

    public WMSPickingRouteID getPickingRouteId(SalesId _salesId)
    {
        WMSPickingRoute     wmsPickingRoute;
            
        select firstonly pickingRouteID, CreatedDateTime, CreatedBy from wmsPickingRoute
            order by CreatedDateTime desc
                where wmsPickingRoute.transRefId == _salesId
                   && wmsPickingRoute.transType == InventTransType::Sales;

        return wmsPickingRoute.pickingRouteID;
    }

    public container calcMetrics(METOrderExtractScreenTmp _rec)
    {
        if (metricsCacheMap.exists(_rec.RecId))
        {
            return metricsCacheMap.lookup(_rec.RecId);
        }

        SalesLine               salesLineLoc;
        METSalesLine            metSalesLineLoc;
        InventDim               lineInventDim;
        InventDim               prevLineInventDim;
        InventItemSalesSetup    inventItemSalesSetup;
        InventDim               inventDimSetup;
        InventTrans             inventTrans;
        InventTransOrigin       inventTransOrigin;
        InventTableModule       inventTableModule;
        ItemId                  prevItemId;
        InventDimId             prevInventDimId;
        UnitOfMeasureSymbol     prevSalesUnit;
        SalesQty                prevSalesQty;
        real                    prevSalesUnitWeight;
        real                    prevSalesUnitVolume;
        real                    prevCWActualWeight;
        real                    prevAISWeight;
        RefRecId                prevIISRecId;
        UnitOfMeasureSymbol     prevMETSalesUnit;
        UnitOfMeasureSymbol     prevMETAltSalesUnit;
        UnitOfMeasureSymbol     prevUnitInvent;
        METCase                 cases;
        METBrokenCase           brokenCase;
        METGrossWeight          orderedWeight;
        METUOMVolume            orderedVolume;
        METCase                 actualCases;
        METBrokenCase           actualBrokenCase;
        METUOMVolume            actualVolume;
        METGrossWeight          actualWeight;
        InventQty               reservedOnOrderQty;
        InventQty               cummReservPhysical, cummReservOrdered, cummOnOrder;
        InventTransId           currentInventTransId;
        boolean                 lineChanged;

        while select SalesQty, SalesUnit, ItemId, InventDimId, RecId, InventTransId from salesLineLoc
        order by salesLineLoc.InventTransId asc
            where salesLineLoc.SalesId     == _rec.SalesId
                && salesLineLoc.SalesStatus == SalesStatus::Backorder
        join lineInventDim
            where lineInventDim.inventDimId == salesLineLoc.InventDimId
        join SalesUnitWeight, SalesUnitVolume, CWActualWeight, AISWeight, RecId from metSalesLineLoc
            where metSalesLineLoc.SalesLine          == salesLineLoc.RecId
        outer join UnitId, RecId from inventTableModule
            where inventTableModule.ItemId     == salesLineLoc.ItemId
                && inventTableModule.ModuleType == ModuleInventPurchSales::Invent
        outer join RecId, METSalesUnit, METAltSalesUnit from inventItemSalesSetup
            where inventItemSalesSetup.ItemId == salesLineLoc.ItemId
        outer join RecId from inventTransOrigin
            where inventTransOrigin.InventTransId     == salesLineLoc.InventTransId
                && inventTransOrigin.ReferenceCategory == InventTransType::Sales
        outer join Qty, StatusIssue from inventTrans
            where inventTrans.InventTransOrigin == inventTransOrigin.RecId
                && (inventTrans.StatusIssue == StatusIssue::ReservPhysical
                    || inventTrans.StatusIssue == StatusIssue::ReservOrdered
                    || inventTrans.StatusIssue == StatusIssue::OnOrder)
        exists join inventDimSetup
            where inventDimSetup.InventDimId  == inventItemSalesSetup.InventDimId
                && inventDimSetup.InventSiteId == lineInventDim.InventSiteId
        {
            if (currentInventTransId && currentInventTransId != salesLineLoc.InventTransId)
            {
                lineChanged = true;
            }

            if (lineChanged)
            {
                boolean prevIsCaseType   = prevIISRecId
                                    && prevMETSalesUnit    == prevSalesUnit
                                    && prevMETAltSalesUnit != prevSalesUnit;

                boolean prevIsBrokenType = prevIISRecId
                                    && prevMETSalesUnit    != prevSalesUnit
                                    && prevMETAltSalesUnit == prevSalesUnit;

                if (prevIsCaseType)
                {
                    cases += prevSalesQty;

                    InventQty totalQty = abs(cummReservPhysical + cummReservOrdered + cummOnOrder);

                    if (totalQty != 0)
                    {
                        METCase totalQtyInSalesUnit = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(
                        prevItemId,
                        prevInventDimId,
                        totalQty,
                        prevUnitInvent,
                        prevSalesUnit,
                        NoYes::No,
                        NoYes::No);

                        actualCases  += totalQtyInSalesUnit;
                        actualVolume += METWHSPhysDimUOMSite::convertVolume(prevItemId, totalQtyInSalesUnit, prevSalesUnit, prevLineInventDim);

                        if (prevCWActualWeight == 0 && prevAISWeight == 0)
                        {
                            actualWeight += METWHSPhysDimUOMSite::convertWeight(prevItemId, totalQtyInSalesUnit, prevSalesUnit, prevLineInventDim);
                        }
                    }

                    if (prevCWActualWeight != 0)
                    {
                        actualWeight += prevCWActualWeight;
                    }
                    else if (prevAISWeight != 0)
                    {
                        actualWeight += prevAISWeight;
                    }
                }
                else if (prevIsBrokenType)
                {
                    brokenCase += prevSalesQty;

                    InventQty reservedQty = abs(cummReservPhysical + cummReservOrdered);
                    reservedOnOrderQty = reservedQty > 0 ? reservedQty : abs(cummOnOrder);

                    InventQty totalQtyAllStatuses = abs(cummReservPhysical + cummReservOrdered + cummOnOrder);

                    if (reservedOnOrderQty != 0)
                    {
                        METBrokenCase reservedOnOrderQtyInSalesUnit = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(
                        prevItemId,
                        prevInventDimId,
                        reservedOnOrderQty,
                        prevUnitInvent,
                        prevMETSalesUnit,
                        NoYes::No,
                        NoYes::No);

                        actualBrokenCase += reservedOnOrderQty - reservedOnOrderQtyInSalesUnit;
                    }

                    if (totalQtyAllStatuses != 0)
                    {
                        actualVolume += METWHSPhysDimUOMSite::convertVolume(prevItemId, totalQtyAllStatuses, prevUnitInvent, prevLineInventDim);

                        if (prevCWActualWeight == 0 && prevAISWeight == 0)
                        {
                            actualWeight += METWHSPhysDimUOMSite::convertWeight(prevItemId, totalQtyAllStatuses, prevUnitInvent, prevLineInventDim);
                        }
                    }

                    if (prevCWActualWeight != 0)
                    {
                        actualWeight += prevCWActualWeight;
                    }
                    else if (prevAISWeight != 0)
                    {
                        actualWeight += prevAISWeight;
                    }
                }

                orderedWeight += prevSalesQty * prevSalesUnitWeight;
                orderedVolume += prevSalesQty * prevSalesUnitVolume;

                cummReservPhysical = 0;
                cummReservOrdered  = 0;
                cummOnOrder        = 0;
                lineChanged        = false;
            }

            if (inventTrans.RecId)
            {
                if (inventTrans.StatusIssue == StatusIssue::ReservPhysical)
                {
                    cummReservPhysical += inventTrans.Qty;
                }
                else if (inventTrans.StatusIssue == StatusIssue::ReservOrdered)
                {
                    cummReservOrdered  += inventTrans.Qty;
                }
                else if (inventTrans.StatusIssue == StatusIssue::OnOrder)
                {
                    cummOnOrder        += inventTrans.Qty;
                }
            }

            currentInventTransId = salesLineLoc.InventTransId;
            prevItemId           = salesLineLoc.ItemId;
            prevInventDimId      = salesLineLoc.InventDimId;
            prevSalesUnit        = salesLineLoc.SalesUnit;
            prevSalesQty         = salesLineLoc.SalesQty;
            prevSalesUnitWeight  = metSalesLineLoc.SalesUnitWeight;
            prevSalesUnitVolume  = metSalesLineLoc.SalesUnitVolume;
            prevCWActualWeight   = metSalesLineLoc.CWActualWeight;
            prevAISWeight        = metSalesLineLoc.AISWeight;
            prevIISRecId         = inventItemSalesSetup.RecId;
            prevMETSalesUnit     = inventItemSalesSetup.METSalesUnit;
            prevMETAltSalesUnit  = inventItemSalesSetup.METAltSalesUnit;
            prevUnitInvent       = inventTableModule.UnitId;
            prevLineInventDim.data(lineInventDim);
        }

        // Process last line
        if (prevItemId)
        {
            boolean prevIsCaseType   = prevIISRecId
                                && prevMETSalesUnit    == prevSalesUnit
                                && prevMETAltSalesUnit != prevSalesUnit;

            boolean prevIsBrokenType = prevIISRecId
                                && prevMETSalesUnit    != prevSalesUnit
                                && prevMETAltSalesUnit == prevSalesUnit;

            if (prevIsCaseType)
            {
                cases += prevSalesQty;

                InventQty totalQty = abs(cummReservPhysical + cummReservOrdered + cummOnOrder);

                if (totalQty != 0)
                {
                    METCase actualCasesInSalesUnit = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(
                    prevItemId,
                    prevInventDimId,
                    totalQty,
                    prevUnitInvent,
                    prevSalesUnit,
                    NoYes::No,
                    NoYes::No);

                    actualCases  += actualCasesInSalesUnit;
                    actualVolume += METWHSPhysDimUOMSite::convertVolume(prevItemId, actualCasesInSalesUnit, prevSalesUnit, prevLineInventDim);

                    if (prevCWActualWeight == 0 && prevAISWeight == 0)
                    {
                        actualWeight += METWHSPhysDimUOMSite::convertWeight(prevItemId, actualCasesInSalesUnit, prevSalesUnit, prevLineInventDim);
                    }
                }

                if (prevCWActualWeight != 0)
                {
                    actualWeight += prevCWActualWeight;
                }
                else if (prevAISWeight != 0)
                {
                    actualWeight += prevAISWeight;
                }
            }
            else if (prevIsBrokenType)
            {
                brokenCase += prevSalesQty;

                InventQty reservedQty = abs(cummReservPhysical + cummReservOrdered);
                reservedOnOrderQty = reservedQty > 0 ? reservedQty : abs(cummOnOrder);

                InventQty totalQtyAllStatuses = abs(cummReservPhysical + cummReservOrdered + cummOnOrder);

                if (reservedOnOrderQty != 0)
                {
                    METBrokenCase reservedOnOrderQtyInSalesUnit = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(
                    prevItemId,
                    prevInventDimId,
                    reservedOnOrderQty,
                    prevUnitInvent,
                    prevMETSalesUnit,
                    NoYes::No,
                    NoYes::No);

                    actualBrokenCase += reservedOnOrderQty - reservedOnOrderQtyInSalesUnit;
                }

                if (totalQtyAllStatuses != 0)
                {
                    actualVolume += METWHSPhysDimUOMSite::convertVolume(prevItemId, totalQtyAllStatuses, prevUnitInvent, prevLineInventDim);

                    if (prevCWActualWeight == 0 && prevAISWeight == 0)
                    {
                        actualWeight += METWHSPhysDimUOMSite::convertWeight(prevItemId, totalQtyAllStatuses, prevUnitInvent, prevLineInventDim);
                    }
                }

                if (prevCWActualWeight != 0)
                {
                    actualWeight += prevCWActualWeight;
                }
                else if (prevAISWeight != 0)
                {
                    actualWeight += prevAISWeight;
                }
            }

            orderedWeight += prevSalesQty * prevSalesUnitWeight;
            orderedVolume += prevSalesQty * prevSalesUnitVolume;
        }

        // Positions: 1=Cases 2=BrokenCase 3=OrderedWeight 4=OrderedVolume
        //            5=ActualCases 6=ActualBrokenCase 7=ActualVolume 8=ActualWeight
        container result = [cases, brokenCase, orderedWeight, orderedVolume,
                        actualCases, actualBrokenCase, actualVolume, actualWeight];
        metricsCacheMap.insert(_rec.RecId, result);
        return result;
    }

