    public void clearTmpTable()
    {
        delete_from metOrderExtractScreenTmp;

        METOrderExtractScreenTmpDS_DS.research();
    }

    public void setTmpSelection(SalesId _salesId, NoYes _selected)
    {
        ttsbegin;

        if (_selected)
        {
            select firstonly forupdate metOrderExtractScreenTmp
                where metOrderExtractScreenTmp.SalesId == _salesId
                && metOrderExtractScreenTmp.Selection == NoYes::No;
        }
        else
        {
            select firstonly forupdate metOrderExtractScreenTmp
                where metOrderExtractScreenTmp.SalesId == _salesId
                    && metOrderExtractScreenTmp.Selection == NoYes::Yes;
        }

        if (metOrderExtractScreenTmp.RecId)
        {
            metOrderExtractScreenTmp.Selection = _selected;
            metOrderExtractScreenTmp.update();
        }
        ttscommit;
    }

public boolean hasAnyRecordsMarked()
{
    select firstonly RecId from metOrderExtractScreenTmp
        where metOrderExtractScreenTmp.Selection == NoYes::Yes;
    return (metOrderExtractScreenTmp.RecId != 0);
}

    /// <summary>
    /// Returns true only if EVERY marked order belongs to a CSD warehouse.
    /// Only called once open-shipment and picklist checks have both cleared.
    /// </summary>
    private boolean checkMarkedOrdersCSD()
    {
        SalesTable      salesTableLoc;
        InventLocation  inventLocation;

        select firstonly RecId from metOrderExtractScreenTmp
            where metOrderExtractScreenTmp.Selection == NoYes::Yes
        exists join salesTableLoc
            where salesTableLoc.SalesId == metOrderExtractScreenTmp.SalesId
        notexists join inventLocation
            where inventLocation.InventLocationId == salesTableLoc.InventLocationId
            && inventLocation.METCSDWarehouse == NoYes::Yes;

        return metOrderExtractScreenTmp.RecId == 0;
    }

    /// <summary>
    /// Enable or disable buttons based on records selection
    /// </summary>
    public void enableOrDisableButtons()
    {
        boolean hasSelection = element.hasAnyRecordsMarked();
        boolean isExtracted         = metOrderExtractScreenParameters.parmExtracted() == METOrderExtractStatus::Extracted;
        boolean checkPicklist;
        boolean anyProcessing = false;
        boolean picklistOk = false;              // true = no picklist blocking issue found
        
        if (hasSelection)
        {
            SalesTable                  salesTableLoc;

            select firstonly RecId from salesTableLoc
                where salesTableLoc.METProcessing == NoYes::Yes
                exists join metOrderExtractScreenTmp
                    where metOrderExtractScreenTmp.SalesId == salesTableLoc.SalesId
                    && metOrderExtractScreenTmp.Selection == NoYes::Yes;

            anyProcessing = (salesTableLoc.RecId != 0);

            checkPicklist = this.checkMarkedOrdersPicklist();           
            
        }

        // Enable or disable controls based on selection status
        METOrderExtractScreenModifyDialog.enabled(hasSelection && checkPicklist);
        Calculate.enabled(hasSelection);        

        UpdateStatusFormButtonControl.enabled(hasSelection && !isExtracted);
        METSalesPickingListGeneration.enabled(hasSelection && !isExtracted);        
    }

    /// <summary>
    /// Returns true when none of the marked orders have an associated picklist.
    /// If any marked order has a picklist number (i.e. a WMS picking route/line exists for the SalesId),
    /// this returns false.
    /// </summary>
    /// <returns>true if none of the marked orders have a picklist; otherwise, false.</returns>
    private boolean checkMarkedOrdersPicklist()
    {
        SalesTable                  salesTableLoc;
        WMSPickingRoute             wmsPickingRoute;

        select firstonly RecId from metOrderExtractScreenTmp
                where metOrderExtractScreenTmp.Selection == NoYes::Yes
            exists join salesTableLoc
                where salesTableLoc.SalesId == metOrderExtractScreenTmp.SalesId
                && (salesTableLoc.METOrderExtractStatus != METOrderExtractStatus::Open || salesTableLoc.METAllowBackOrders == NoYes::No)
            exists join wmsPickingRoute
                where wmsPickingRoute.transRefId == metOrderExtractScreenTmp.SalesId
                && wmsPickingRoute.transType == InventTransType::Sales;
        
        return metOrderExtractScreenTmp.RecId == 0;
    }

    /// <summary>
    /// CB123 SalesOrderExtractForCSD
    /// This method is check if the csd salesorder is found
    /// </summary>
    /// <param name = "_salesTable">Sales table buffer</param>
    /// <returns>true or false</returns>
    private boolean salesOrderHasNonOpenShipment(SalesId _salesId)
    {
        METSalesOrderShipmentLoadLines  metSalesOrderShipmentLoadLines;
        METSalesOrderShipmentLoadHeader metSalesOrderShipmentLoadHeader;

        select firstonly RecId, ShipmentId from metSalesOrderShipmentLoadLines
            where   metSalesOrderShipmentLoadLines.OrderNum == _salesId
        exists join metSalesOrderShipmentLoadHeader
            where metSalesOrderShipmentLoadHeader.ShipmentId == metSalesOrderShipmentLoadLines.ShipmentId
            && metSalesOrderShipmentLoadHeader.ShipmentStatus != MetShipmentStatus::Open;

        return metSalesOrderShipmentLoadLines.RecId != 0;
    }

    /// <summary>
    /// Returns true if a picklist (WMS picking route) exists for the given sales order.
    /// </summary>
    /// <param name = "_salesId">Sales order id</param>
    /// <returns>true if a picklist exists for the sales order; otherwise, false.</returns>
    private boolean checkIfPicklistExistsForSalesOrder(SalesId _salesId)
    {
        WMSPickingRoute             wmsPickingRoute;

        select firstonly RecId from wmsPickingRoute
            where wmsPickingRoute.transRefId == _salesId
            && wmsPickingRoute.transType == InventTransType::Sales;
    
        return wmsPickingRoute.RecId != 0;
    }

