            public boolean validate()
            {
                boolean ret;

                ret = super();

                METOrderExtractScreenTmp metOrderExtractScreenTmpLocal = METOrderExtractScreenTmpDS_ds.cursor();

                if (ret && metOrderExtractScreenTmpLocal.Selection == NoYes::Yes)
                {
                    SalesTable salesTableLoc;
                    
                    select firstonly METOrderExtractStatus, METProcessing 
                        from salesTableLoc
                        where salesTableLoc.SalesId == metOrderExtractScreenTmpLocal.SalesId;

                    salesTableLoc = SalesTable_ds.cursor();

                    boolean  haveOpenShipments = element.salesOrderHasNonOpenShipment(salesTableLoc.SalesId);
                    boolean  checkPicklist = element.checkIfPicklistExistsForSalesOrder(metOrderExtractScreenTmpLocal.SalesId);

                    if (salesTableLoc.METOrderExtractStatus == METOrderExtractStatus::Extracted
                        && (haveOpenShipments || checkPicklist))
                    {
                        // To validate any sales order selected which is already Extracted throw an error
                        error(strFmt("@MET:METSalesOrderAlreadyExtracted", metOrderExtractScreenTmpLocal.SalesId));
                        ret = false;
                    }

                    if (salesTableLoc.METProcessing == NoYes::Yes)
                    {
                        warning(strFmt("@MET:METOrderExtractingWarning", metOrderExtractScreenTmpLocal.SalesId));
                    }
                }

                return ret;
            }

