        /// <summary>
        /// Select all records in the grid
        /// </summary>
        public void clicked()
        {
            SalesTable salesTableLocal;
            salesTableLocal = SalesTable_ds.getFirst(false);
            
            while (salesTableLocal.RecId)
            {
                SalesTable salesTableLoc;

                select firstonly METOrderExtractStatus, METProcessing from salesTableLoc
                    where salesTableLoc.SalesId == salesTableLocal.SalesId;

                if(SalesTableLoc.METOrderExtractStatus != METOrderExtractStatus::Extracted)
                {
                    element.setTmpSelection(salesTableLoc.SalesId, NoYes::Yes);
                    selectAll = true;
                    if (salesTableLoc.METProcessing == NoYes::Yes)
                    {
                        warning(strFmt("@MET:METOrderExtractingWarning", salesTableLoc.SalesId));
                    }
                }
                else
                {
                    element.setTmpSelection(salesTableLoc.SalesId, NoYes::No);
                }

                salesTableLocal = SalesTable_ds.getNext();
            }
            
            super();

            element.task(#taskRefresh);
            SalesTable_ds.refresh();
            element.enableOrDisableButtons();
            selectAll = false;
        }

