        /// <summary>
        /// Calculate totals.
        /// CS - CB173_SalesOrderExtract - PS
        /// </summary>
        [SuppressBPWarning('BPCheckNestedLoopInCode', 'This is reqiored to calculate all the values of selected records.')]
        public void clicked()
        {
            #define.Million(1000000000)
            selectAll = true;
            super();

            METTotalPallets totalPal, estTotalPal;
            Weight          weight, actualWeight;
            Volume          volume, actualVolume;
            METCase         cases, actualCases;
            METBrokenCase   brokenCase, actBrokenCases;
            SalesId         salesIdLoc;
            Volume          soPallet, estimatedPallet;   
        
            totalPal    = 0;
            estTotalPal = 0;

            boolean usePalletVolume = false;
            METWHSPalletVolume palletVolume = 0;
            SalesTable salesTableLoc;

            while select metOrderExtractScreenTmp
                where metOrderExtractScreenTmp.Selection == NoYes::Yes
            {
                SalesId             valueLoc    = metOrderExtractScreenTmp.SalesId;
                SalesLine           salesLineLoc;
                METSalesLine        metsalesLine;
                Volume              perSalesVolume = 0, perEstimatedVolume = 0;                 

                // Get warehouse pallet volume (assume same warehouse for all orders in extract)
                // Note: If different warehouses, you'll need additional logic
                if (!usePalletVolume)
                {
                    METInventLocation   metInventLocation;
                    InventLocation      inventLocation;

                    select firstonly WHSPalletVolume from metInventLocation
                    join InventLocationId from salesTableLoc
                        where salesTableLoc.SalesId == valueLoc
                    join RecId from inventLocation
                        where inventLocation.RecId == metInventLocation.InventLocation
                        && inventLocation.InventLocationId == salesTableLoc.InventLocationId;
            
                    // Validation: Check if pallet volume is configured
                    if (metInventLocation.RecId != 0 && metInventLocation.WHSPalletVolume > 0)
                    {
                        palletVolume = metInventLocation.WHSPalletVolume;
                        usePalletVolume = true;
                    }
                }


                while select salesLineLoc
                    where salesLineLoc.SalesId == valueLoc
                    && salesLineLoc.SalesStatus == SalesStatus::Backorder
                        join SalesUnitWeight, SalesUnitVolume from metsalesLine
                            where metsalesLine.SalesLine  == salesLineLoc.RecId
                            && metsalesLine.OrderExtractStatus != METOrderExtractStatus::Extracted
                {
                    weight          += salesLineLoc.SalesQty * metsalesLine.SalesUnitWeight;

                    Volume          volumePerSalesLine  = salesLineLoc.SalesQty * metsalesLine.SalesUnitVolume;

                    volume          += volumePerSalesLine;
                    perSalesVolume  += volumePerSalesLine;
                    cases           += salesLineLoc.displayMETcases();
                    brokenCase      += salesLineLoc.displayMETBrokenCase();
                    actBrokenCases  += salesLineLoc.displayMETActualBrokenCase();
                    actualCases     += salesLineLoc.displayMETActualCases();

                    Volume          actualUnitVolumePerSalesLine = salesLineLoc.displayMETActualUnitVolume();

                    actualVolume    += actualUnitVolumePerSalesLine;
                    perEstimatedVolume += actualUnitVolumePerSalesLine;
                    actualWeight    += salesLineLoc.displayMETActualWeight();
                }

                

                real orderPallets = 0;
                real orderEstimatedPallets = 0;
        
                if (usePalletVolume && palletVolume > 0)
                {
                    // Calculate pallets for THIS SPECIFIC ORDER                    
                    orderPallets = System.Math::Ceiling(perSalesVolume / palletVolume);
                    orderEstimatedPallets = System.Math::Ceiling(perEstimatedVolume / palletVolume);
                }
                else
                {
                    // Fallback: Use 1.0 as default pallet volume
                    orderPallets = System.Math::Ceiling(perSalesVolume / 1.0);
                    orderEstimatedPallets = System.Math::Ceiling(perEstimatedVolume / 1.0);
                }

                // round per-sales pallets and accumulate
                soPallet += orderPallets;
                estimatedPallet += orderEstimatedPallets;
            }
			
            totalPal = soPallet;
            estTotalPal = estimatedPallet;

            SumOfOrderedVolume.realValue(volume);
            SumOfOrderedlWeight.realValue(weight);
            SumOfEstimatedVolume.realValue(actualVolume);
            SumOfEstimatedlWeight.realValue(actualWeight);
            SumOfOrderedCases.value(cases);
            SumOfEstimatedCases.value(actualCases);
            SumOfOrderedBrokenCases.value(brokenCase);
            SumOfEstimatedBrokenCases.value(actBrokenCases);
            totalPallet.value(totalPal);
            TotalEstimatedPallets.value(estTotalPal);

            selectAll = false;

            //element.redraw();
        }

