        /// <summary>
        /// This method is to update the status
        /// CB173_SalesOrderExtract - PS
        /// </summary>
        /// <param name = "_salesTable">SalesTable</param>
        private void updateOrderExtractScreenRec(SalesTable _salesTable)
        {
            #OCCRetryCount

            SalesLine       salesLine;
            METSalesLine    metSalesLine;
            boolean         updateSalesTable;

            //SysApplicationInsightsEventTelemetry telemetryEvent = new SysApplicationInsightsEventTelemetry("Sales order extract - Update status");
            //telemetryEvent.addProperty("StartTime", DateTimeUtil::getSystemDateTime());

            try
            {
                ttsbegin;
                _salesTable.selectForUpdate(true);

                if (_salesTable.METOrderExtractStatus == METOrderExtractStatus::ReadyForExtract)
                {
                    _salesTable.METOrderExtractStatus =  METOrderExtractStatus::Open;
                    updateSalesTable = true;
                }
                else 
                {
                    if (_salesTable.METOrderExtractStatus == METOrderExtractStatus::Open)
                    {
                        updateSalesTable = false;

                        if (!_salesTable.METRoute || !_salesTable.METRouteStopNum)
                        {
                            updateSalesTable = checkFailed(strFmt("@MET:SOExtractRouteWarning", _salesTable.SalesId));
                        }
                        else
                        {
                            //Check if atleast one salesline has reserved quantity;
                            while select salesLine
                            where salesLine.SalesId == _salesTable.SalesId
                            && salesLine.SalesStatus != SalesStatus::Canceled
                            && salesLine.SalesStatus != SalesStatus::Invoiced
                            && !salesLine.SourcingCompanyId
                            join metSalesLine where metSalesLine.SalesLine == salesLine.RecId
                            && metSalesLine.OrderExtractStatus != METOrderExtractStatus::Extracted
                            {
                                if (salesLine.reservedPhysical())
                                {
                                    updateSalesTable = true;
                                    break;
                                }
                            }
                            if (!updateSalesTable)
                            {
                                //If the SO has just Intercompany lines then update status to 'Ready for extract'
                                select firstonly RecId from salesLine
                                    where   salesLine.SalesId == _salesTable.SalesId
                                    &&      salesLine.SalesStatus != SalesStatus::Canceled
                                    &&      salesLine.SourcingCompanyId
                                    join    metSalesLine 
                                    where   metSalesLine.SalesLine == salesLine.RecId
                                    &&      metSalesLine.OrderExtractStatus != METOrderExtractStatus::Extracted;
                                if (salesline.RecId)
                                {
                                    updateSalesTable = true;
                                }

                            }
                        }

                        if (updateSalesTable)
                        {
                            _salesTable.METOrderExtractStatus =  METOrderExtractStatus::ReadyForExtract;
                        }
                    }
                }

                if (updateSalesTable)
                {
                    _salesTable.update();
                    info(StrFmt("@MET:METBulkUpdateInfo", _salesTable.SalesId));
                }
            
                ttscommit;
            }
            catch (Exception::Error)
            {
                error("@MET:METBulkUpdateError");
            }

            catch (Exception::UpdateConflict)
            {
                if (appl.ttsLevel() == 0)
                {
                    if (xSession::currentRetryCount() >= #RetryNum)
                    {
                        throw Exception::UpdateConflictNotRecovered;
                    }
                    else
                    {
                        retry;
                    }
                }
                else
                {
                    throw Exception::UpdateConflict;
                }
            }
        }

        /// <summary>
        /// This method is to update the status
        /// CB173_SalesOrderExtract - PS

        /// Bug347577 -
        /// This method is to update the status in bulk based on the marked orders from the grid,
        /// this is to avoid the refresh issue in the grid as we are updating the records one by one in the above method
        /// which is called from the grid and it causes refresh issue in the grid.
        /// </summary>
        private void updateOrderExtractScreenMap()
        {
            #OCCRetryCount
            SalesTable      salesTableLoc;
            METSalesLine    metSalesLine;
            SalesLine       salesLineLoc;
            int             processedCount = 0;
            int             updatedCount = 0;
            int             errorCount = 0;
            List            salesTableList = new List(Types::String);
            utcdatetime      startTime = DateTimeUtil::getSystemDateTime();
            utcdatetime      endTime;


            //Build the list of sales order to be updated based upon pre-checks.
            while select metOrderExtractScreenTmp
                where metOrderExtractScreenTmp.Selection == NoYes::Yes
            {
                SalesId currentSalesId = metOrderExtractScreenTmp.SalesId;

                select firstonly METRoute, METRouteStopNum, RecId from salesTableLoc
                    where salesTableLoc.SalesId == currentSalesId;

                if(!salesTableLoc.RecId)
                {
                    continue;
                }

                //Check if sales header has route and route stop number, if not then skip the record and show warning message
                if (!salesTableLoc.METRoute || !salesTableLoc.METRouteStopNum)
                {
                    checkFailed(strFmt("@MET:SOExtractRouteWarning", currentSalesId));
                    errorCount++;
                    continue;
                }

                SalesTableList.addEnd(currentSalesId);
            }

            ListEnumerator salesTableLE = salesTableList.getEnumerator();
            while (salesTableLE.moveNext())
            {
                SalesId currentSalesId = salesTableLE.current();

                try
                {
                    ttsbegin;

                    select firstonly forupdate salesTableLoc where salesTableLoc.SalesId == currentSalesId;
                    if(!salesTableLoc.RecId)
                    {
                        ttscommit;
                        continue;
                    }

                    SalesTableloc.skipDataMethods(true);
                    SalesTableloc.skipDatabaseLog(true);
                    metSalesLine.skipDatabaseLog(true);
                    metSalesLine.skipDataMethods(true);
                    metSalesLine.allowIndexHint(true);
                    salesTableLoc.skipBusinessEvents(true);
                    metSalesLine.skipBusinessEvents(true);

                    if(salesTableLoc.METOrderExtractStatus == METOrderExtractStatus::ReadyForExtract)
                    {
                        salesTableLoc.METOrderExtractStatus = METOrderExtractStatus::Open;
                        salesTableLoc.update();
                        update_recordset metSalesLine 
                            setting OrderExtractStatus = METOrderExtractStatus::Open    
                                where metSalesLine.OrderExtractStatus == METOrderExtractStatus::ReadyForExtract
                                exists join salesLineLoc
                                    where metSalesLine.SalesLine == salesLineLoc.RecId &&
                                        saleslineloc.SalesId == salesTableLoc.SalesId  &&
                                        saleslineloc.SalesStatus == SalesStatus::Backorder;
                    
                        updatedCount++;
                    }
                    else if (salesTableLoc.METOrderExtractStatus == METOrderExtractStatus::Open)
                    {
                        salesTableLoc.METOrderExtractStatus = METOrderExtractStatus::ReadyForExtract;
                        salesTableLoc.update();
                        update_recordset metSalesLine

                            setting OrderExtractStatus = METOrderExtractStatus::ReadyForExtract    
                                where metSalesLine.OrderExtractStatus == METOrderExtractStatus::Open
                                exists join salesLineLoc
                                    where metSalesLine.SalesLine == salesLineLoc.RecId &&
                                        saleslineloc.SalesId == salesTableLoc.SalesId  &&
                                        saleslineloc.SalesStatus == SalesStatus::Backorder;
                        updatedCount++;
                    }
                    ttscommit;
                    processedCount++;
                }
                catch (Exception::Error)
                {
                    errorCount++;
                    error("@MET:METBulkUpdateError");
                }
                catch (Exception::UpdateConflict)
                {
                    if (appl.ttsLevel() == 0)
                    {
                        if (xSession::currentRetryCount() >= #RetryNum)
                        {
                            errorCount++;
                            throw Exception::UpdateConflictNotRecovered;
                        }
                        else
                        {
                            retry;
                        }
                    }
                    else
                    {
                        errorCount++;
                        throw Exception::UpdateConflict;
                    }
                }
            }
            if(processedCount || updatedCount || errorCount)
            {
                info(strFmt("@MET:METBulkUpdateSummary", processedCount, updatedCount, errorCount));
            }
            //info(strFmt("Start time %1 End time: %2", startTime, DateTimeUtil::getSystemDateTime()));
            
        }

        /// <summary>
        /// CB123 SalesOrderExtractForCSD
        /// This method is check if the csd salesorder is found
        /// </summary>
        /// <param name = "_salesTable">Sales table buffer</param>
        /// <returns>true or false</returns>
        private boolean checkForCSDSalesOrder(SalesTable _salesTable)
        {
            boolean         csdOrderFound = false;
            InventLocation  inventLocation;

            select firstonly METNumberOfCustomers from inventLocation
                where   inventLocation.InventLocationId == _salesTable.InventLocationId
                &&      inventLocation.METCSDWarehouse == NoYes::Yes;

            if (inventLocation.RecId != 0)
            {
                csdCustomerLimit = inventLocation.METNumberOfCustomers;
                csdWareHouse     = inventLocation.InventLocationId;
                csdOrderFound    = true;    
            }

            return csdOrderFound;
        }

